**price.go**

```go
package lesson

func Price(cents int, member bool) int {
	if member {
		return cents * 90 / 100
	}
	return cents
}
```

**price_test.go**

```go
package lesson

import "testing"

func TestPrice(t *testing.T) {
	t.Run("regular price", func(t *testing.T) {
		if got := Price(1000, false); got != 1000 {
			t.Fatalf("got %d; want 1000", got)
		}
	})
	t.Run("member discount", func(t *testing.T) {
		if got := Price(1000, true); got != 900 {
			t.Fatalf("got %d; want 900", got)
		}
	})
}
```

**Run it**

```bash
go test ./...
go test -v -run '^TestPrice$/^member_discount$' ./...
go test -list '^Test' ./...
```

The first command chooses the package set. The second then selects one hierarchical test name inside that set.

**counter.go**

```go
package lesson

import "sync"

type Counter struct {
	mu    sync.Mutex
	value int
}

func (c *Counter) Add(delta int) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.value += delta
}

func (c *Counter) Value() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.value
}
```

**counter_test.go**

```go
package lesson

import (
	"sync"
	"testing"
)

func TestCounterConcurrent(t *testing.T) {
	var counter Counter
	var wg sync.WaitGroup
	for range 10 {
		wg.Go(func() { counter.Add(1) })
	}
	wg.Wait()
	if got := counter.Value(); got != 10 {
		t.Fatalf("Value = %d; want 10", got)
	}
}

func TestBroaderCases(t *testing.T) {
	if testing.Short() {
		t.Skip("broader cases omitted in short mode")
	}
	for delta := -100; delta <= 100; delta++ {
		var counter Counter
		counter.Add(delta)
		if got := counter.Value(); got != delta {
			t.Fatalf("delta %d: got %d", delta, got)
		}
	}
}
```

**Run it**

```bash
go test -race -count=1 ./...
go test -shuffle=42 -count=1 ./...
go test -short -timeout=30s -count=1 ./...
```

The race run exercises real concurrent access, while the short-mode branch explicitly states which broader work it omits.
